def read_au_file(path, opts):
    data = open(path,'rb').read() if path != "-" else sys.stdin.buffer.read()
    filesize = len(data)
    if len(data) < 24 or data[0:4] != b'.snd':
        raise ValueError("not au")
    header_size = struct.unpack('>I', data[4:8])[0]
    data_size = struct.unpack('>I', data[8:12])[0]
    encoding = struct.unpack('>I', data[12:16])[0]
    sample_rate = struct.unpack('>I', data[16:20])[0]
    channels = struct.unpack('>I', data[20:24])[0]
    # encoding: 1=mu-law 8, 2=8-bit linear, 3=16-bit linear, 4=24-bit, 5=32-bit, 6=float, 7=double, 23=G721? etc.
    # Map to bits/enc
    enc_map = {1:(8,"mu-law"), 2:(8,"signed-integer"), 3:(16,"signed-integer"), 4:(24,"signed-integer"), 5:(32,"signed-integer"), 6:(32,"floating-point"), 7:(64,"floating-point")}
    if encoding not in enc_map:
        raise ValueError("unsupported au encoding")
    bits, enc_str = enc_map[encoding]
    # data starts at header_size
    raw = data[header_size:header_size+data_size] if data_size != 0xFFFFFFFF else data[header_size:]
    if opts.get('ignore_length'):
        raw = data[header_size:]
    # decode similar to wav but big-endian for PCM?
    # AU PCM is big-endian
    samples = None
    ch = channels
    if enc_str == "mu-law":
        floats = [mulaw_decode(b) for b in raw]
        nframes = len(floats)//ch
        samples = [[0.0]*nframes for _ in range(ch)]
        for i in range(nframes):
            for c in range(ch):
                samples[c][i]=floats[i*ch+c]
    elif enc_str == "signed-integer":
        if bits == 8:
            # 8-bit signed? AU 8-bit linear is signed? Yes.
            vals = list(struct.unpack('b'*len(raw), raw))
            floats = [v/128.0 for v in vals]  # 8-bit signed: -128..127 -> /128?
            # Actually for 8-bit signed, max 127/128=0.992, min -1.0. Good.
            nframes = len(floats)//ch
            samples = [[0.0]*nframes for _ in range(ch)]
            for i in range(nframes):
                for c in range(ch):
                    samples[c][i]=floats[i*ch+c]
        elif bits == 16:
            n = len(raw)//2
            vals = struct.unpack('>'+'h'*n, raw[:n*2])
            floats = [v/32768.0 for v in vals]
            nframes = len(floats)//ch
            samples = [[0.0]*nframes for _ in range(ch)]
            for i in range(nframes):
                for c in range(ch):
                    samples[c][i]=floats[i*ch+c]
        elif bits == 24:
            n = len(raw)//3
            vals=[]
            for i in range(n):
                b0,b1,b2 = raw[i*3],raw[i*3+1],raw[i*3+2]
                v = (b0<<16)|(b1<<8)|b0 if False else (b0<<16)|(b1<<8)|b2
                # Actually big-endian 24: b0 is MSB
                v = (b0<<16)|(b1<<8)|b2
                if v & 0x800000: v-=0x1000000
                vals.append(v/8388608.0)
            nframes=len(vals)//ch
            samples=[[0.0]*nframes for _ in range(ch)]
            for i in range(nframes):
                for c in range(ch):
                    samples[c][i]=vals[i*ch+c]
        elif bits == 32:
            n=len(raw)//4
            vals=struct.unpack('>'+'i'*n, raw[:n*4])
            floats=[v/2147483647.0 if v!= -2147483648 else -1.0 for v in vals]
            for idx in range(len(floats)):
                if floats[idx]>1: floats[idx]=1
                if floats[idx]<-1: floats[idx]=-1
            nframes=len(floats)//ch
            samples=[[0.0]*nframes for _ in range(ch)]
            for i in range(nframes):
                for c in range(ch):
                    samples[c][i]=floats[i*ch+c]
    elif enc_str == "floating-point":
        if bits==32:
            n=len(raw)//4
            vals=struct.unpack('>'+'f'*n, raw[:n*4])
            nframes=len(vals)//ch
            samples=[[0.0]*nframes for _ in range(ch)]
            for i in range(nframes):
                for c in range(ch):
                    samples[c][i]=float(vals[i*ch+c])
        else:
            n=len(raw)//8
            vals=struct.unpack('>'+'d'*n, raw[:n*8])
            nframes=len(vals)//ch
            samples=[[0.0]*nframes for _ in range(ch)]
            for i in range(nframes):
                for c in range(ch):
                    samples[c][i]=float(vals[i*ch+c])
    # precision
    if enc_str=="mu-law": precision=14
    elif enc_str=="floating-point": precision=25 if bits==32 else 54
    else: precision=bits
    enc_soxi = {"signed-integer":"Signed Integer PCM","mu-law":"u-law","floating-point":"Floating Point PCM"}[enc_str] if enc_str in ("signed-integer","mu-law","floating-point") else enc_str
    # au 8-bit signed vs? Soxi for au? Need to check.
    return {"samples":samples,"rate":sample_rate,"channels":channels,"bits":bits,"encoding":enc_str,"enc_str":enc_soxi,"filetype":"au","precision":precision,"filesize":filesize,"comments":"","nframes":nframes}

def write_au_file(path, samples, rate, channels, bits, encoding, comments=""):
    enc = encoding.lower().replace("_","-") if encoding else "signed-integer"
