def write_audio_file(path, samples, rate, channels, fopts):
    # fopts: type, encoding, bits, channels, rate, etc. for output
    # Determine type
    ftype = fopts.get('type')
    if path == "-n" or path == "--null":
        return write_null_file(path, samples, rate, channels, 32, "signed-integer")
    if path == "-d" or path == "--default-device":
        raise DeviceError()
    if path == "-p" or path == "--sox-pipe":
        # alias for -t sox -
        fopts2=dict(fopts); fopts2['type']='sox'
        return write_sox_file("-", samples, rate, channels, fopts2)
    if path == "-":
        # stdout: need type
        if ftype is None:
            raise NoHandlerError(path, ftype)
        return write_audio_by_type("-", samples, rate, channels, ftype, fopts)
    # Regular file
    if ftype is None:
        # Detect from filename, or default to input type? Caller should have set default from input if None.
        # For output without -t and with extension, detect.
        ftype = detect_type_from_filename(path)
        if ftype is None:
            # No extension and no -t: use input type? Caller handles. For now, default to wav? Or error?
            raise NoHandlerError(path, ftype)
    return write_audio_by_type(path, samples, rate, channels, ftype, fopts)

def write_audio_by_type(path, samples, rate, channels, ftype, fopts):
    ftype_low=ftype.lower()
    bits=fopts.get('bits')
    encoding=fopts.get('encoding')
    # Defaults for output if not specified: use input's? Caller should have set bits/encoding from input if None? For wav, default is 32? Actually output defaults to input where possible.
    # For now, if bits/encoding None, use defaults per type:
    # wav default: 32-bit signed? Or 16? From earlier, default wav output for synth (32-bit input) was 32-bit. For 16-bit input, output 16? Let's see: converting 16-bit wav to wav without -b gives same bits? Probably yes (same as input). So caller must set defaults from input. If still None, use 32 for wav, 16 for au? etc.
    # We'll handle defaults here if None:
    if bits is None:
        if ftype_low in ("wav","wavpcm","amb"): bits=32
        elif ftype_low in ("au","snd"): bits=16
        elif ftype_low in ("aiff","aif"): bits=16
        elif ftype_low in ("aifc","aiffc"): bits=16
        elif ftype_low=="dat": bits=64
        elif ftype_low=="sox": bits=32
        else: bits=16
    if encoding is None:
        if ftype_low in ("wav","wavpcm","amb"):
            # default based on bits? For 8-bit, unsigned; else signed? Or float? We'll default to signed for 16/24/32, unsigned for 8.
            if bits==8: encoding="unsigned-integer"
            else: encoding="signed-integer"
        elif ftype_low in ("au","snd"): encoding="signed-integer"
        elif ftype_low in ("aiff","aif","aifc","aiffc"): encoding="signed-integer"
        elif ftype_low=="dat": encoding="floating-point"
        elif ftype_low=="sox": encoding="signed-integer"
        else: encoding="signed-integer"
    # Normalize bits to int
    try: bits=int(bits)
    except: bits=32
