    elif ftype_low in ("au","snd"):
        return write_au_file(path, samples, rate, channels, bits, encoding, fopts.get('comment',""))
    elif ftype_low in ("aiff","aif"):
        return write_aiff_file(path, samples, rate, channels, bits, encoding, fopts.get('comment',""), is_aifc=False)
    elif ftype_low in ("aifc","aiffc"):
        return write_aiff_file(path, samples, rate, channels, bits, encoding, fopts.get('comment',""), is_aifc=True)
    elif ftype_low=="dat":
        return write_dat_file(path, samples, rate, channels, bits, encoding, fopts.get('comment',""))
    elif ftype_low=="sox":
        return write_sox_file(path, samples, rate, channels, fopts)
    elif ftype_low in ("raw","s1","s8","sb","s2","s16","sw","s3","s24","s4","s32","sl","u1","u8","ub","sou","fssd","u2","u16","uw","u3","u24","u4","u32","f4","f32","f8","f64","al","la","lu","ul"):
