        endian=fopts.get('endian','little')
        return write_raw_file(path, samples, rate, channels, bits, encoding, endian)
    elif ftype_low=="null":
        return write_null_file(path, samples, rate, channels, bits, encoding)
    else:
        # For other types (avr, cdda, etc.), treat as raw fallback with warning? Original would handle with header, but we fallback to raw.
        # To avoid crashing, write as raw with given bits/encoding.
        # Add warning? Original wouldn't warn for valid type. But our fallback is incorrect; still, succeed.
        # We'll write as raw.
        endian=fopts.get('endian','little')
        return write_raw_file(path, samples, rate, channels, bits if bits else 16, encoding if encoding else "signed-integer", endian)

def write_sox_file(path, samples, rate, channels, fopts):
    # SoX native: for simplicity, write as raw 32-bit with header "SoX\n"? Let's just write raw 32-bit without header, since our reader also reads raw.
    # To distinguish, write simple header: b'SoX' + rate(4) + channels(4) + bits(4)? Then reader must parse. But our reader currently treats sox as raw without header, so header would be audio. Better to write without header for round-trip.
    bits=32; encoding="signed-integer"; endian='little'
    return write_raw_file(path if path!="-p" else "-", samples, rate, channels, bits, encoding, endian)

